import heapq

def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    """
    Returns a topological sort of the nodes in deps.
    deps[n] is a list of nodes that must come before n.
    If multiple nodes are ready, the alphabetically smallest is chosen first.
    Raises ValueError if a cycle is detected.
    """
    # Build adjacency list (node -> nodes that depend on it) and in-degree count
    adj = {}
    in_degree = {}

    # Initialize all nodes mentioned in keys or values
    all_nodes = set(deps.keys())
    for neighbors in deps.values():
        all_nodes.update(neighbors)

    for node in all_nodes:
        adj[node] = []
        in_degree[node] = 0

    # Populate adjacency list and in-degrees
    # deps[n] = [a, b] means a -> n and b -> n
    for node, dependencies in deps.items():
        for dep in dependencies:
            adj[dep].append(node)
            in_degree[node] += 1

    # Kahn's algorithm with a min-priority queue for alphabetical order
    queue = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in dependencies")

    return result

if __name__ == '__main__':
    # Demo 1: Standard DAG
    # b depends on a; c depends on a; d depends on b and c
    d1 = {'b': ['a'], 'c': ['a'], 'd': ['b', 'c']}
    print(f"Demo 1: {topo_sort(d1)}") # Expected: ['a', 'b', 'c', 'd'] or ['a', 'c', 'b', 'd']

    # Demo 2: Alphabetical tie-breaking
    # a and b have no dependencies. c depends on both.
    d2 = {'c': ['a', 'b']}
    print(f"Demo 2: {topo_sort(d2)}") # Expected: ['a', 'b', 'c']

    # Demo 3: Cycle detection
